for c in C:
 c['source_manifest']=[{k:S[n][k] for k in ['sys_id','name','join_fields','all_ap_ids','file','line_start','line_end','block_sha256']} for n in dict.fromkeys(c['primary_source_ids']+c['supporting_source_ids'])]
 c['score']=10*c['consequence']+3*c['testability']+2*c['join_route']-2*c['cost_tier']
for label,key in [('priority_rank',lambda x:(-x['score'],x['test_id'])),('testability_rank',lambda x:(-x['testability'],x['cost_tier'],x['test_id'])),('consequence_rank',lambda x:(-x['consequence'],x['test_id']))]:
 for n,c in enumerate(sorted(C,key=key),1):c[label]=n
C.sort(key=lambda x:x['priority_rank'])
def export(name,rs):
 (P/(name+'.jsonl')).write_text(''.join(json.dumps(r,ensure_ascii=False)+'\n' for r in rs))
 with (P/(name+'.csv')).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=rs[0]);w.writeheader();w.writerows({k:json.dumps(v,ensure_ascii=False) if isinstance(v,(dict,list)) else v for k,v in r.items()} for r in rs)
export('cards',C);export('priority-subchecks',rows)
priorities=[]
for family in dict.fromkeys(r['priority'] for r in rows):
 rr=[r for r in rows if r['priority']==family]
 priorities.append(dict(priority=family,prior_gap=rr[0]['prior_gap'],subchecks=[r['check_id'] for r in rr],decisions=[r['disposition'] for r in rr],source_ids=sorted({n for r in rr for n in r['source_ids']}),stage='source-level substantive screen completed; no matched investigation',stop_reason='All three recorded branches have an explicit decision and original-record dependency; further progress needs targeted evidence or a different predicate, not parameter multiplication'))
export('priority-coverage',priorities)
export('source-coverage',[dict(sys_id=s['sys_id'],name=s['name'],subchecks=[r['check_id'] for r in rows if n in r['source_ids']],status='screened_in_this_priority_pass' if any(n in r['source_ids'] for r in rows) else 'not_revisited_in_this_pass',block_sha256=s['block_sha256']) for n,s in S.items()])
(P/'sources.jsonl').write_text((OLD/'sources.jsonl').read_text())
print('Priorities',len(priorities),'subchecks',len(rows),'cards',len(C),'new',sum(c['kind']=='proposed_new' for c in C))
